local procedure DoBatchSend(var EDocument: Record "E-Document"; var EDocumentService: Record "E-Document Service")
    var
        TempEDocMappingLogs: Record "E-Doc. Mapping Log" temporary;
        EDocExport: Codeunit "E-Doc. Export";
