        end;

        GuidedExperience.InsertApplicationFeature(CompanyDetailsTitleTxt, CompanyDetailsShortTitleTxt, CompanyDetailsDescriptionTxt, 2, ObjectType::Codeunit, Codeunit::"Company Details Checklist Item");
