        GlobalLanguage(CurrentGlobalLanguage);

        GuidedExperience.InsertLearnLink(LearnBusinessCentralTitleTxt, LearnBusinessCentralShortTitleTxt, LearnBusinessCentralDescriptionTxt, 0, LearnBusinessCentralLinkTxt);
