begin
        if RecRef.Get("Record ID") then begin
            if RecRef.Number = Database::"Shpfy Catalog" then
                exit(RecRef.Field(Catalog.FieldNo(Catalog.Name)).Value());
            RecRef.SetRecFilter();
            PKFilter := RecRef.GetView();
            repeat
                Pos := StrPos(PKFilter, '=FILTER(');
                if Pos <> 0 then begin
                    PKFilter := CopyStr(PKFilter, Pos + 8);
                    Result += Delimiter + CopyStr(PKFilter, 1, StrPos(PKFilter, ')') - 1);
                    Delimiter := ',';
                end;
            until Pos = 0;
        end;
    end;

