                            Result.Append('<div class="productDescription">');
                            Result.Append(MarketingText);
                            Result.Append('</div>');
                            Result.Append('<br>');
                        end
                    end;

            if Shop."Sync Item Attributes" then
                AddAtributeHtml(ItemNo, Result, LanguageCode);

            ProductBodyHtml := Result.ToText();
        end;
